"""Life, Unpaused: an activity destination board, not a treatment-photo hero."""
def render(block,img,media,link,cta,pages,data):
 out='''<section class="unpause" data-scene="sport" aria-labelledby="headline"><div class="unpause-intro"><p class="eyebrow"><span class="live-dot" aria-hidden="true"></span> Mendocino Physical Therapy / Ukiah, CA</p><h1 id="headline">Life.<br><em>Unpaused.</em></h1><p class="unpause-lede">The match. The stairs. The everyday stuff.<br>Start with the part of life you want back.</p><div class="poster-meta"><span>Different Bodies.</span><span>Different Starting Points.</span><span>Your Own Goals.</span></div></div><div class="route-stations"><h2>What’s On Pause?</h2><p class="station-hint">Choose Your Starting Point <span aria-hidden="true">↙</span></p><div class="route-picks" role="group" aria-label="Choose the part of life you want to return to"><button type="button" data-goal="sport" aria-pressed="true"><span class="station-number">01</span><span><strong>The Game.</strong><small>Sports / ACL Injury</small></span><span class="station-arrow" aria-hidden="true">↗</span></button><button type="button" data-goal="everyday" aria-pressed="false"><span class="station-number">02</span><span><strong>The Everyday.</strong><small>Walking / Balance</small></span><span class="station-arrow" aria-hidden="true">↗</span></button><button type="button" data-goal="recovery" aria-pressed="false"><span class="station-number">03</span><span><strong>The Next Chapter.</strong><small>After Surgery / New Knee</small></span><span class="station-arrow" aria-hidden="true">↗</span></button><button type="button" data-goal="golf" aria-pressed="false"><span class="station-number">04</span><span><strong>The Next Round.</strong><small>Golf / TPI Assessment</small></span><span class="station-arrow" aria-hidden="true">↗</span></button></div></div><div class="route-result"><div class="destination-graphic" aria-hidden="true"><svg viewBox="0 0 760 250"><path class="map-track" d="M0 210H180Q230 210 270 150L350 50Q390 0 455 30L550 120Q590 160 650 150L760 110"/><path id="motion-path" class="motion-line" d="M0 210H180Q230 210 270 150L350 50Q390 0 455 30L550 120Q590 160 650 150L760 110"/><circle cx="350" cy="50" r="12"/></svg><span id="destination-word">Play.</span><span class="destination-caption">Your Destination / Your Pace</span></div><div class="scene-copy" aria-live="polite" aria-atomic="true"><p class="eyebrow" id="goal-kicker">01 / Back To Sport</p><h2 id="goal-title">A Way Back To Your Game.</h2><p id="goal-copy">An ACL injury or a sports setback brings its own questions. Explore the practice’s sports rehabilitation and meet the people behind your care.</p><div class="result-actions"><a id="goal-link" class="button-link" href="sports-rehabilitation/">Explore Sports Care <span aria-hidden="true">↗</span></a><a class="text-link" href="book-an-appointment/">Plan A First Visit ↗</a></div></div></div></section>'''
 out+='''<div class="practical-rail"><span>Before You Visit</span><a href="insurance/">Insurance ↗</a><a href="faqs/">What To Bring ↗</a><a href="contact-us/">Find Us ↗</a></div>'''
 names=[b['text'] for b in pages['meet-the-team']['blocks'] if b['tag']=='h3' and not b['text'].startswith('Get started')]
 out+='<section class="real-people"><div class="people-intro"><p class="eyebrow">People From Here</p><h2>Local Faces. Real Care.</h2><p>Six members of your care team.<br>Get to know who is here.</p>'+link('meet-the-team','Meet The Whole Team ↗')+'</div><div class="people-strip">'
 for i,name in enumerate(names):out+='<a href="meet-the-team/">'+img(media('meet-the-team',i),name)+f'<span>{name}</span></a>'
 out+='</div></section><section class="practice-reference"><div class="reference-heading"><p class="eyebrow">Care, In Plain Sight.</p><h2>The Practice, <br>In Detail.</h2></div><div class="reference-rows"><details class="content-detail"><summary>How We Work</summary><div class="reference-copy">'
 for i in range(8):out+=block('home',i,'h3' if pages['home']['blocks'][i]['tag'].startswith('h') else 'p')
 out+=img(media('home',0),'Outdoor photograph featured by Mendocino Physical Therapy','reference-photo')+'</div></details><details class="content-detail"><summary>Care Areas</summary><div>'+block('home',8,'p')+'<div class="expertise-list">'
 icons=[a['file'] for a in data['media'] if any(x in a['file'] for x in ['04-tape','05-heart','06-lungs','07-pelvis','08-dumbell'])]
 for j,i in enumerate(range(9,14)):out+='<a href="physical-therapy-1/">'+img(icons[j],'')+block('home',i,'h3')+'<span aria-hidden="true">↗</span></a>'
 out+='</div></div></details><details class="content-detail"><summary>Fitness & Community</summary><div class="reference-copy">'+block('home',14,'h3')+block('home',15)+img(media('home',8),'Fitness class pictured on the practice website','reference-photo')+link('functional-fitness-classes','Schedules, Classes & Registration ↗')+'</div></details></div></section>'
 return out+cta('')
